  { order: 3, step_name: 'qbo_collection_loader', finish_node: 'Finish qbo_collection_loader' },
  { order: 4, step_name: 'fc_completion_sync', finish_node: 'Finish fc_completion_sync' },
  { order: 5, step_name: 'recognition_trigger_apply', finish_node: 'Finish recognition_trigger_apply' },
  { order: 6, step_name: 'fc_anchor_match_refresh', finish_node: 'Finish fc_anchor_match_refresh' },
  { order: 7, step_name: 'fulfillment_audit_refresh', finish_node: 'Finish fulfillment_audit_refresh' },
  { order: 8, step_name: 'classification_transition_apply', finish_node: 'Finish classification_transition_apply' },
];

function finishContext(finishNodeName) {
  try {
    return $(finishNodeName).first()?.json ?? null;
  } catch (error) {
    return null;
  }
}

const pipelineRunId = $('Validate Pipeline Webhook Payload').first().json.pipeline_run_id;
const stepResults = [];
for (const spec of stepSpecs) {
  const ctx = finishContext(spec.finish_node);
  if (!ctx) continue;
  const ownResult = (ctx.step_results ?? []).find((step) => step.step_name === spec.step_name);
  if (ownResult) stepResults.push(ownResult);
}

const total_steps_completed = stepResults.filter((step) => step.status === 'success').length;
const total_steps_failed = stepResults.filter((step) => step.status === 'failed').length;
const total_rows_affected = stepResults.reduce((sum, step) => sum + Number(step.rows_affected || 0), 0);
const hardFailed = stepResults.some((step) => step.status === 'failed' && step.step_order <= 6);
const softFailed = stepResults.some((step) => step.status === 'failed' && step.step_order >= 7);
const status = hardFailed ? 'failed' : (softFailed ? 'partial' : 'success');

return [{ json: {
  pipeline_run_id: pipelineRunId,
  step_results: stepResults,
  run_patch: {
    status,
    finished_at: new Date().toISOString(),
    summary: {
      total_steps_completed,
      total_steps_failed,
      total_rows_affected,
      error_summary: total_steps_failed ? `${total_steps_failed} pipeline step(s) failed` : null,
      notable_findings: status === 'failed' ? 'Workflow 26 halted on a hard-step failure.' : 'Workflow 26 completed 8-step C.b orchestration.',
      steps: stepResults,
    },
  },
}}];
